import{_ as e,o as n,c as i,a1 as r}from"./chunks/framework.DxqwKiYY.js";const g=JSON.parse('{"title":"Modul 1 - Persiapan dan Konfigurasi","description":"","frontmatter":{},"headers":[],"relativePath":"Training WebGIS BIG/Modul 1 - Persiapan dan Konfigurasi.md","filePath":"Training WebGIS BIG/Modul 1 - Persiapan dan Konfigurasi.md"}'),o={name:"Training WebGIS BIG/Modul 1 - Persiapan dan Konfigurasi.md"};function t(s,a,u,d,l,m){return n(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="modul-1-persiapan-dan-konfigurasi" tabindex="-1">Modul 1 - Persiapan dan Konfigurasi <a class="header-anchor" href="#modul-1-persiapan-dan-konfigurasi" aria-label="Permalink to &quot;Modul 1 - Persiapan dan Konfigurasi&quot;">​</a></h1><p>Persiapan dan konfigurasi dasar dalam merancang serta membangun aplikasi WebGIS. Mempersiapkan perangkat lunak yang diperlukan dan pengaturan ruang kerja di Visual Studio Code, instalasi framework Next.js, hingga pengelolaan sistem menggunakan Git dan GitHub untuk kebutuhan kolaborasi pengembangan.</p><h2 id="tujuan-modul" tabindex="-1"><strong>Tujuan Modul</strong> <a class="header-anchor" href="#tujuan-modul" aria-label="Permalink to &quot;**Tujuan Modul**&quot;">​</a></h2><ul><li>Peserta mampu menyiapkan folder proyek dan membukanya menggunakan <em>code editor</em> Visual Studio Code.</li><li>Peserta dapat melakukan inisialisasi dan konfigurasi <em>framework</em> Next.js menggunakan perintah terminal (<code>npx create-next-app@latest</code>) serta menjalankannya di <em>localhost</em>.</li><li>Peserta mampu membuat repositori baru di GitHub dan mengunggah proyek lokal ke repositori tersebut menggunakan perintah GitBash.</li><li>Peserta dapat melakukan proses <em>cloning</em> (menyalin) proyek dari GitHub ke perangkat lokal, serta menginstal <em>library</em> yang dibutuhkan menggunakan NPM (<code>npm install</code>).</li><li>Peserta memahami dan mampu mempraktikkan alur kerja pengiriman serta pengambilan pembaruan proyek (<em>version control</em>) menggunakan perintah dasar Git seperti <code>git pull</code>, <code>git add</code>, <code>git commit</code>, dan <code>git push</code>.</li></ul><h2 id="materi" tabindex="-1">Materi <a class="header-anchor" href="#materi" aria-label="Permalink to &quot;Materi&quot;">​</a></h2><p><a href="./Modul 1 - Persiapan dan Konfigurasi/Instalasi Aplikasi.html">Instalasi Aplikasi</a></p><p><a href="./Modul 1 - Persiapan dan Konfigurasi/Persiapan dan Konfigurasi Framework.html">Persiapan dan Konfigurasi Framework</a></p>',7)])])}const k=e(o,[["render",t]]);export{g as __pageData,k as default};
